def fizzbuzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def parsear_duracion(s):
    if not s:
        return 0
    partes = s.split()
    total = 0
    for parte in partes:
        if parte.endswith('h'):
            total += int(parte[:-1]) * 60
        elif parte.endswith('m'):
            total += int(parte[:-1])
    return total

def es_palindromo(s):
    cleaned = ''.join(c.lower() for c in s if c.isalnum())
    return cleaned == cleaned[::-1]

def aplanar(lista):
    result = []
    for item in lista:
        if isinstance(item, list):
            result.extend(aplanar(item))
        else:
            result.append(item)
    return result

def buscar(lista, x):
    izquierda = 0
    derecha = len(lista) - 1
    while izquierda <= derecha:
        medio = (izquierda + derecha) // 2
        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            izquierda = medio + 1
        else:
            derecha = medio - 1
    return -1

def agrupar_por(items, clave):
    agrupados = {}
    for item in items:
        valor = item[clave]
        if valor not in agrupados:
            agrupados[valor] = []
        agrupados[valor].append(item)
    return agrupados

def contar_palabras(texto):
    import re
    palabras = re.findall(r'\b\w+\b', texto.lower())
    diccionario = {}
    for palabra in palabras:
        if palabra not in diccionario:
            diccionario[palabra] = 0
        diccionario[palabra] += 1
    return diccionario

def rotar(lista, n):
    if not lista:
        return []
    n = n % len(lista)
    if n < 0:
        n += len(lista)
    return lista[-n:] + lista[:-n]

def a_romano(n):
    if n < 1 or n > 3999:
        raise ValueError("El número debe estar entre 1 y 3999")

    numeros = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    resultado = []
    for valor, simbolo in numeros:
        while n >= valor:
            resultado.append(simbolo)
            n -= valor

    return ''.join(reversed(resultado))

def from_romano(s):
    roman_map = {
        'I': 1, 'V': 5, 'X': 10,
        'L': 50, 'C': 100,
        'D': 500, 'M': 1000
    }
    result = 0
    prev_value = 0
    for char in reversed(s):
        value = roman_map.get(char, 0)
        if value < prev_value:
            result -= value
        else:
            result += value
        prev_value = value
    return result

def mayor_racha(lista):
    if not lista:
        return None

    max_racha = 0
    max_element = None
    current_racha = 0
    current_element = None

    for i in range(len(lista)):
        if i == 0:
            current_element = lista[i]
            current_racha = 1
        else:
            if lista[i] == current_element:
                current_racha += 1
            else:
                if current_racha > max_racha:
                    max_racha = current_racha
                    max_element = current_element
                current_racha = 1
                current_element = lista[i]

    if current_racha > max_racha:
        max_racha = current_racha
        max_element = current_element

    return (max_element, max_racha)

def a_camel(s):
    words = s.split()
    result = words[0]
    for word in words[1:]:
        result += word[0].upper() + word[1:]
    return result

def a_snake(s):
    if not s:
        return ""
    result = []
    for char in s:
        if char.isupper():
            result.append("-")
        result.append(char.lower())
    return "".join(result)

def primos(n):
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n + 1, i):
                is_prime[j] = False
    return [i for i, prime in enumerate(is_prime) if prime]

def mcd(a, b):
    if a == 0:
        return b
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

def es_anagrama(a, b):
    a = a.lower().replace(' ', '')
    b = b.lower().replace(' ', '')
    return sorted(a) == sorted(b)

def comprimir(s):
    if not s:
        return s

    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            if count > 1:
                s = s[:i-1] + str(count) + s[i:]
                count = 1
            else:
                count = 1

    return s

def balanceado(texto):
    if not texto:
        return True
    open_parens = []
    open_curtas = []
    open_llaves = []
    for char in texto:
        if char == '(':
            open_parens.append(char)
        elif char == '[':
            open_curtas.append(char)
        elif char == '{':
            open_llaves.append(char)
        elif char == ')':
            if not open_parens:
                return False
            open_parens.pop()
        elif char == ']':
            if not open_curtas:
                return False
            open_curtas.pop()
        elif char == '}':
            if not open_llaves:
                return False
            open_llaves.pop()
    return len(open_parens) == 0 and len(open_curtas) == 0 and len(open_llaves) == 0

def transpuesta(m):
    if not m:
        return []
    n = len(m[0])
    return [[m[i][j] for i in range(len(m))] for j in range(n)]

def suma_digitos(n):
    while len(str(n)) > 1:
        n = sum(int(digit) for digit in str(n))
    return n

def raiz_digital(n):
    return suma_digitos(n)

