def sin_duplicados(lista):
    seen = set()
    result = []
    for item in lista:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def n_esimo_mayor(lista, n):
    if n <= 0:
        return None
    seen = set()
    contador = 0
    for num in lista:
        if num not in seen:
            seen.add(num)
            contador += 1
            if contador == n:
                return num
    return None

def formatear_bytes(n):
    if n == 0:
        return '0 B'
    if n < 1024:
        return f'{n} B'
    if n < 1024 * 1024:
        return f'{n / 1024:.1f} KB'
    if n < 1024 * 1024 * 1024:
        return f'{n / (1024 * 1024):.1f} MB'
    return f'{n / (1024 * 1024 * 1024):.1f} GB'

def en_lotes(lista, tamano):
    if not lista:
        return []
    return [lista[i:i+tamano] for i in range(0, len(lista), tamano)]
